-- Timetable and period management
CREATE TABLE IF NOT EXISTS timetable_periods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,day_of_week SMALLINT NOT NULL CHECK(day_of_week BETWEEN 1 AND 7),starts_at TIME NOT NULL,ends_at TIME NOT NULL,sort_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),UNIQUE(school_id,branch_id,name,day_of_week));
CREATE TABLE IF NOT EXISTS timetable_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE,branch_id UUID REFERENCES branches(id) ON DELETE CASCADE,session_id UUID NOT NULL REFERENCES academic_sessions(id) ON DELETE CASCADE,section_id UUID NOT NULL REFERENCES sections(id) ON DELETE CASCADE,subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,teacher_id UUID NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,day_of_week SMALLINT NOT NULL CHECK(day_of_week BETWEEN 1 AND 7),starts_at TIME NOT NULL,ends_at TIME NOT NULL,room VARCHAR(100),status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS timetable_entries_scope_idx ON timetable_entries(school_id,branch_id,session_id,section_id,day_of_week,starts_at);
CREATE UNIQUE INDEX IF NOT EXISTS timetable_teacher_slot_uq ON timetable_entries(school_id,session_id,teacher_id,day_of_week,starts_at) WHERE status='active';
CREATE UNIQUE INDEX IF NOT EXISTS timetable_section_slot_uq ON timetable_entries(school_id,session_id,section_id,day_of_week,starts_at) WHERE status='active';